  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Stacked area chart of monthly retail sales by category (2020 excluded), with largest category at the bottom of the stack.",
  "data": {
    "url": "path/to/your.csv",
    "format": {
      "type": "csv"
    }
  },
  "transform": [
    {
      "calculate": "toDate(datum.month)",
